contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Param: recipient to pass to withdrawAll. Payable so the test contract can hold/send Ether if needed.
    function run(address recipient) public payable {
        // Require that this test contract is the owner of c so the call is authorized by owner condition.
        require(c.owner() == address(this));

        // record balance of C before the call
        uint256 beforeC = address(c).balance;

        // Attempt the state-changing call as its own top-level statement and capture whether it reverted.
        bool reverted;
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterC = address(c).balance;

        // General rule: when the owner calls withdrawAll, either it reverted, or C's balance is zero afterwards.
        assert(reverted || afterC == 0);
    }

    receive() external payable { }
}

